/**
 * Crease kinds, following Lang's uniaxial box-pleating vocabulary:
 * - hinge: boundaries between flap squares and rivers
 * - ridge: 45 degree lines where axis-parallel creases change direction
 * - axial: axis-parallel contours at integer elevations (elevation 0 is the axis)
 * - conflict: places where neighbouring contours disagree in parity and a
 *   level shifter (not generated by this app) would be needed
 */
export type CreaseKind = 'hinge' | 'ridge' | 'axial' | 'conflict';

/** Mountain, valley, or unassigned. */
export type Assignment = 'M' | 'V' | 'U';

export interface Crease {
  readonly x1: number;
  readonly y1: number;
  readonly x2: number;
  readonly y2: number;
  readonly kind: CreaseKind;
  readonly mv: Assignment;
  /** Elevation for axial creases (0 = axis); lowest elevation for ridges. */
  readonly elevation?: number;
}

export interface CreasePattern {
  /** Unit-length creases on the grid, as generated. Used for checks. */
  readonly creases: readonly Crease[];
  /** The same creases merged into long lines, for drawing. */
  readonly lines: readonly Crease[];
  /** Grid cells (by top-left corner) not cleanly owned by one flap. */
  readonly ambiguousCells: ReadonlyArray<{ readonly x: number; readonly y: number }>;
}
